void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec2 e = 3.0 / iResolution.xy;
    float m = clamp(texture(iChannel1, uv).r * U.p0.x, 0.0, 1.0);
    float dx = texture(iChannel1, uv + vec2(e.x, 0.0)).r - texture(iChannel1, uv - vec2(e.x, 0.0)).r;
    float dy = texture(iChannel1, uv + vec2(0.0, e.y)).r - texture(iChannel1, uv - vec2(0.0, e.y)).r;
    vec2 ripple = vec2(sin(uv.y * 60.0 + iTime * 4.0), cos(uv.x * 60.0 + iTime * 3.0));
    vec2 off = vec2(dx, dy) * U.p0.y + 0.012 * m * ripple;
    vec3 cam = texture(iChannel0, uv).rgb;
    vec3 bent = texture(iChannel0, uv + off).rgb * vec3(0.85, 1.0, 1.08);
    float edge = clamp(length(vec2(dx, dy)) * 5.0, 0.0, 1.0);
    vec3 col = mix(cam, bent, m) + edge * vec3(0.2, 0.8, 1.0) * 0.6;
    fragColor = vec4(col, 1.0);
}
